class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        nums.sort()
        n = len(nums)
        averages = []
        for i in range(n // 2):
            avg = (nums[i] + nums[-i - 1]) / 2
            averages.append(avg)
        return min(averages)
